"""ERPNext as the system of record.

Implements the two-question contract in `protocol.py` against a live ERPNext /
Frappe instance over its REST API. Nothing else in SupplyGuard knows this file
exists — swapping in a different ERP means writing a different class with the
same two methods.

Why ERPNext maps well: the single most important thing SupplyGuard needs to
know is how many units are physically on hand *and genuinely free*, versus on
hand but already promised elsewhere. ERPNext stores exactly that split natively
on `Bin` (`actual_qty` vs `reserved_qty`), which is the spec's "known
allocations" — the number that later catches a supplier saying "yes we have
stock" when that stock is not actually available to us.

Demo domain: automotive fasteners. A car plant buys hex flange screws by the
tens of thousands at a few cents each, which is also why every money value
below travels as `Decimal` and never as a float — a fraction of a cent times
24,000 units is a real number.

Round trips per supplier lookup: ~5. Kept obvious rather than clever.
"""

from __future__ import annotations

import json
import logging
import os
from dataclasses import dataclass
from datetime import date, datetime
from decimal import Decimal
from typing import Any

import httpx

from supplyguard.models import Shortage, SupplierRecord
from supplyguard.phone import InvalidPhoneNumber, mask, normalize, normalize_and_validate
from supplyguard.record.protocol import IncidentNotFound
from supplyguard.vocab import Currency

log = logging.getLogger(__name__)

# ERPNext stores a free-text country name, not a region code. Unmapped
# countries stay None rather than being guessed at — a wrong locale puts the
# calling agent into the wrong language, which is worse than an empty field.
_COUNTRY: dict[str, tuple[str, str]] = {
    "Germany": ("DE", "de-DE"),
    "France": ("FR", "fr-FR"),
    "United Kingdom": ("GB", "en-GB"),
    "United States": ("US", "en-US"),
    "Austria": ("AT", "de-AT"),
    "Italy": ("IT", "it-IT"),
    "Spain": ("ES", "es-ES"),
    "Czech Republic": ("CZ", "cs-CZ"),
    "Poland": ("PL", "pl-PL"),
}

# Certification and line-down cost have no native home in ERPNext. They are
# Custom Fields on Supplier / Material Request; absent means "unknown", which
# the vocabulary already handles as a first-class answer.
CERT_FIELD = "custom_certification"
CERT_EXPIRY_FIELD = "custom_certification_expiry"
LINE_DOWN_COST_FIELD = "custom_line_down_cost_per_hour"
EXPEDITE_FEE_FIELD = "custom_expedite_fee_cap"


@dataclass(frozen=True)
class ERPNextConfig:
    base_url: str
    api_key: str
    api_secret: str
    buying_price_list: str = "Standard Buying"
    #: Warehouses to count stock in. Empty means "every warehouse".
    warehouses: tuple[str, ...] = ()

    @classmethod
    def from_env(cls) -> "ERPNextConfig":
        missing = [
            name
            for name in ("ERPNEXT_BASE_URL", "ERPNEXT_API_KEY", "ERPNEXT_API_SECRET")
            if not os.environ.get(name)
        ]
        if missing:
            raise RuntimeError(
                "ERPNext credentials missing from the environment: "
                + ", ".join(missing)
            )
        raw_warehouses = os.environ.get("ERPNEXT_WAREHOUSES", "")
        return cls(
            base_url=os.environ["ERPNEXT_BASE_URL"].rstrip("/"),
            api_key=os.environ["ERPNEXT_API_KEY"],
            api_secret=os.environ["ERPNEXT_API_SECRET"],
            buying_price_list=os.environ.get(
                "ERPNEXT_BUYING_PRICE_LIST", "Standard Buying"
            ),
            warehouses=tuple(w.strip() for w in raw_warehouses.split(",") if w.strip()),
        )


class ERPNextRecord:
    """A `SystemOfRecord` backed by ERPNext.

    Pass `transport` (e.g. `httpx.MockTransport`) to exercise the real query
    and parsing logic without a network — that is how the demo and the tests
    run, so no test run ever opens a socket.
    """

    def __init__(
        self,
        config: ERPNextConfig,
        *,
        client: httpx.Client | None = None,
        transport: httpx.BaseTransport | None = None,
    ) -> None:
        self._config = config
        self._client = client or httpx.Client(
            base_url=config.base_url,
            headers={
                "Authorization": f"token {config.api_key}:{config.api_secret}",
                "Accept": "application/json",
            },
            transport=transport,
            timeout=30.0,
        )

    @classmethod
    def from_env(cls, **kwargs: Any) -> "ERPNextRecord":
        return cls(ERPNextConfig.from_env(), **kwargs)

    def close(self) -> None:
        self._client.close()

    def __enter__(self) -> "ERPNextRecord":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    # -- the two-question contract ------------------------------------------

    def approved_suppliers_for(self, part_number: str) -> list[SupplierRecord]:
        links = {
            row["supplier"]: row.get("supplier_part_no")
            for row in self._child_rows(
                "Item Supplier",
                parent_doctype="Item",
                parent=part_number,
                fields=["supplier", "supplier_part_no"],
            )
        }
        if not links:
            return []  # nobody supplies this part — an empty list, not an error

        suppliers = self._list(
            "Supplier",
            filters=[["name", "in", list(links)], ["disabled", "=", 0]],
            fields=[
                "name",
                "supplier_name",
                "country",
                "default_currency",
                "mobile_no",
                "on_hold",
                "supplier_primary_contact",
                CERT_FIELD,
                CERT_EXPIRY_FIELD,
            ],
        )

        # ERPNext has no "preferred supplier" flag on the Item Supplier row.
        # The Item's per-company default supplier is the honest equivalent.
        preferred = {
            row["default_supplier"]
            for row in self._child_rows(
                "Item Default",
                parent_doctype="Item",
                parent=part_number,
                fields=["default_supplier"],
            )
            if row.get("default_supplier")
        }

        prices = {
            row["supplier"]: row
            for row in self._list(
                "Item Price",
                filters=[
                    ["item_code", "=", part_number],
                    ["buying", "=", 1],
                    ["price_list", "=", self._config.buying_price_list],
                ],
                fields=["supplier", "price_list_rate", "currency"],
            )
            if row.get("supplier")
        }

        _on_hand, allocations = self._stock(part_number)
        lead_times = self._lead_time_days(part_number)

        records: list[SupplierRecord] = []
        for supplier in suppliers:
            supplier_id = supplier["name"]
            if supplier.get("on_hold"):
                continue  # on hold in ERPNext is not approved to buy from

            phone = self._usable_phone(supplier)
            if phone is None:
                continue  # already logged; a record with a bad number never exists

            price_row = prices.get(supplier_id, {})
            region, locale = _COUNTRY.get(supplier.get("country") or "", (None, None))

            records.append(
                SupplierRecord(
                    supplier_id=supplier_id,
                    supplier_name=supplier.get("supplier_name") or supplier_id,
                    phone=phone,
                    region=region,
                    locale=locale,
                    part_number=part_number,
                    supplier_part_number=links.get(supplier_id),
                    approved=True,
                    preferred=supplier_id in preferred,
                    contract_unit_price=_decimal(price_row.get("price_list_rate")),
                    currency=Currency.parse(
                        price_row.get("currency") or supplier.get("default_currency")
                    ),
                    lead_time_days=int(lead_times.get(supplier_id, 0)),
                    certification=supplier.get(CERT_FIELD),
                    certification_expiry=_date(supplier.get(CERT_EXPIRY_FIELD)),
                    known_allocations=allocations,
                    max_historical_fill=self._max_historical_fill(
                        part_number, supplier_id
                    ),
                )
            )

        # Preferred first, then cheapest contract price. Deliberate and fixed —
        # which supplier gets called first is never left to guesswork.
        # (Ordering compares raw price figures; mixing currencies in one buying
        # price list would make that comparison meaningless, so don't.)
        records.sort(key=lambda r: (not r.preferred, r.contract_unit_price))
        return records

    def incident(self, incident_id: str) -> Shortage:
        doc = self._doc("Material Request", incident_id)
        items = doc.get("items") or []
        if not items:
            raise IncidentNotFound(f"{incident_id} has no requested items")

        item = items[0]
        part_number = item["item_code"]
        on_hand, _allocations = self._stock(part_number)
        item_doc = self._doc("Item", part_number)

        return Shortage(
            incident_id=doc["name"],
            part_number=part_number,
            part_name=item_doc.get("item_name") or part_number,
            units_required=int(_decimal(item.get("qty"))),
            units_on_hand=on_hand,
            line_down_at=_datetime(
                item.get("schedule_date") or doc.get("schedule_date")
            ),
            line_down_cost_per_hour=_decimal(doc.get(LINE_DOWN_COST_FIELD)),
            expedite_fee_cap=(
                _decimal(doc[EXPEDITE_FEE_FIELD])
                if doc.get(EXPEDITE_FEE_FIELD) is not None
                else None
            ),
            currency=Currency.parse(doc.get("currency")),
        )

    # -- ERPNext specifics ---------------------------------------------------

    def _usable_phone(self, supplier: dict[str, Any]) -> str | None:
        """ERPNext stores phone numbers as free text — `(0)30 23125-4` is
        perfectly valid to it. Strip formatting, then demand real E.164.

        A supplier whose number fails is skipped, loudly and masked, rather
        than dialled on a guess.
        """
        raw = self._raw_phone(supplier)
        if not raw:
            log.warning(
                "supplier %s has no phone number in ERPNext — skipped",
                supplier["name"],
            )
            return None
        try:
            return normalize_and_validate(raw)
        except InvalidPhoneNumber:
            log.warning(
                "supplier %s has an unusable phone number %s in ERPNext "
                "(no country code, or not E.164) — skipped, never dialled",
                supplier["name"],
                mask(normalize(raw)),
            )
            return None

    def _raw_phone(self, supplier: dict[str, Any]) -> str | None:
        contact_name = supplier.get("supplier_primary_contact")
        if contact_name:
            contact = self._doc("Contact", contact_name, missing_ok=True) or {}
            numbers = contact.get("phone_nos") or []
            for key in ("is_primary_mobile_no", "is_primary_phone"):
                for row in numbers:
                    if row.get(key) and row.get("phone"):
                        return row["phone"]
            if numbers and numbers[0].get("phone"):
                return numbers[0]["phone"]
        return supplier.get("mobile_no")

    def _stock(self, part_number: str) -> tuple[int, int]:
        """(on hand, already promised elsewhere), summed across warehouses.

        `Bin` holds one row per item x warehouse, so a single-row read would
        quietly under-report a plant that stores the same screw in two places.
        """
        filters: list[list[Any]] = [["item_code", "=", part_number]]
        if self._config.warehouses:
            filters.append(["warehouse", "in", list(self._config.warehouses)])
        rows = self._list(
            "Bin",
            filters=filters,
            fields=[
                "warehouse",
                "actual_qty",
                "reserved_qty",
                "reserved_qty_for_production",
            ],
        )
        on_hand = sum(_decimal(r.get("actual_qty")) for r in rows)
        allocated = sum(
            _decimal(r.get("reserved_qty")) + _decimal(r.get("reserved_qty_for_production"))
            for r in rows
        )
        return int(on_hand), int(allocated)

    def _lead_time_days(self, part_number: str) -> dict[str, int]:
        rows = self._child_rows(
            "Item Default",
            parent_doctype="Item",
            parent=part_number,
            fields=["default_supplier", "lead_time_days"],
        )
        return {
            r["default_supplier"]: int(_decimal(r.get("lead_time_days")))
            for r in rows
            if r.get("default_supplier")
        }

    def _max_historical_fill(self, part_number: str, supplier_id: str) -> int:
        rows = self._list(
            "Purchase Order Item",
            filters=[["item_code", "=", part_number]],
            fields=["qty", "parent"],
            parent="Purchase Order",
            extra={"order_by": "qty desc", "limit_page_length": 1},
        )
        return int(_decimal(rows[0].get("qty"))) if rows else 0

    # -- transport -----------------------------------------------------------

    def _list(
        self,
        doctype: str,
        *,
        filters: list[list[Any]] | None = None,
        fields: list[str] | None = None,
        parent: str | None = None,
        extra: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        params: dict[str, Any] = {"limit_page_length": 0}
        if filters:
            params["filters"] = json.dumps(filters)
        if fields:
            params["fields"] = json.dumps(fields)
        if parent:
            params["parent"] = parent
        if extra:
            params.update(extra)
        return self._get(f"/api/resource/{doctype}", params) or []

    def _child_rows(
        self,
        doctype: str,
        *,
        parent_doctype: str,
        parent: str,
        fields: list[str],
    ) -> list[dict[str, Any]]:
        """Frappe requires `parent=<Parent DocType>` to read a child table."""
        return self._list(
            doctype,
            filters=[["parent", "=", parent]],
            fields=fields,
            parent=parent_doctype,
        )

    def _doc(
        self, doctype: str, name: str, *, missing_ok: bool = False
    ) -> dict[str, Any]:
        try:
            return self._get(f"/api/resource/{doctype}/{name}", None) or {}
        except httpx.HTTPStatusError as exc:
            if exc.response.status_code == 404:
                if missing_ok:
                    return {}
                raise IncidentNotFound(f"{doctype} {name!r} does not exist") from exc
            raise

    def _get(self, path: str, params: dict[str, Any] | None) -> Any:
        response = self._client.get(path, params=params)
        response.raise_for_status()
        # Parse floats straight into Decimal. ERPNext sends prices as JSON
        # numbers; a screw at 0.0412 must never exist as a float, not even
        # for the instant between parsing and construction.
        return json.loads(response.text, parse_float=Decimal).get("data")


def _decimal(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date(value: Any) -> date | None:
    if not value:
        return None
    return date.fromisoformat(str(value)[:10])


def _datetime(value: Any) -> datetime:
    if not value:
        raise ValueError("incident has no scheduled date")
    text = str(value)
    return datetime.fromisoformat(text if " " in text or "T" in text else f"{text} 00:00:00")
