#!/usr/bin/env bash
# Run SupplyGuard without fighting the shell's ROS PYTHONPATH.
#
#   ./run.sh test      offline tests only — never dials, never hits the network
#   ./run.sh demo      walk ERPNext and print the CALL-E body without sending it
#   ./run.sh call      the guarded live-call test (needs all three .env guards)
#
# Anything after the subcommand is passed straight through.
set -euo pipefail
cd "$(dirname "$0")"

PY="$PWD/.venv/bin/python"
[ -x "$PY" ] || { echo "no venv at $PY" >&2; exit 1; }

# The shell exports a ROS PYTHONPATH whose launch_testing pytest plugin breaks
# collection here. Drop it for the duration of the run.
run() { env -u PYTHONPATH "$PY" "$@"; }


case "${1:-test}" in
  test) shift || true; [ "${1:-}" = "--" ] && shift; run -m pytest test -v -m "not live" "$@" ;;
  demo) shift || true; [ "${1:-}" = "--" ] && shift; run demo/erpnext_demo.py "$@" ;;
  call) shift || true; [ "${1:-}" = "--" ] && shift; run -m pytest test -v -m live -s "$@" ;;
  *)    echo "usage: ./run.sh {test|demo|call} [extra args]" >&2; exit 2 ;;
esac

