def incident_panel(shortage: Shortage) -> str:
    return f"""
<section>
  <h2>Shortage · {e(shortage.incident_id)}</h2>
  <div class="shortfall">{shortage.shortfall_units:,}<small> units short</small></div>
  <dl class="grid" style="margin-top:14px">
    <dt>Part</dt><dd class="mono">{e(shortage.part_number)}</dd>
    <dt></dt><dd>{e(shortage.part_name)}</dd>
    <dt>Required</dt><dd>{shortage.units_required:,}</dd>
    <dt>On hand</dt><dd>{shortage.units_on_hand:,}</dd>
    <dt>Line stops</dt><dd>{shortage.line_down_at:%Y-%m-%d %H:%M}</dd>
    <dt>Cost / hour</dt>
    <dd>{e(shortage.line_down_cost_per_hour)} {e(shortage.currency.value)}</dd>
  </dl>
  <p class="note">On hand is summed across every warehouse holding this part.
  A shortfall is never negative.</p>
</section>"""


def queue_panel(
    suppliers: list[SupplierRecord], selected: SupplierRecord | None
) -> str:
    rows = []
    for rank, s in enumerate(suppliers, start=1):
        pref = '<span class="pill pref">preferred</span>' if s.preferred else ""
        cert = (
            f"{e(s.certification)}<br><span class='pill'>to {e(s.certification_expiry)}</span>"
            if s.certification
            else "<span class='pill'>unknown</span>"
        )
        klass = ' class="sel"' if selected and s.supplier_id == selected.supplier_id else ""
        rows.append(f"""
    <tr{klass}>
      <td>{rank}</td>
      <td><a href="/?supplier={e(s.supplier_id)}">{e(s.supplier_name)}</a><br>
          <span class="pill mono">{e(s.masked_phone())}</span> {pref}</td>
      <td class="mono">{e(s.contract_unit_price)}<br>
          <span class="pill">{e(s.currency.value)}</span></td>
      <td>{s.lead_time_days}d</td>
      <td>{cert}</td>
      <td class="mono">{s.max_historical_fill:,}</td>
    </tr>""")
    return f"""
<section>
  <h2>Call queue — preferred first, then cheapest</h2>
  <table>
    <thead><tr><th>#</th><th>Supplier</th><th>Contract</th><th>Lead</th>
      <th>Certification</th><th>Best fill</th></tr></thead>
    <tbody>{"".join(rows)}</tbody>
  </table>
  <p class="note">Order is fixed, never guessed. A cheaper supplier still ranks
  below the preferred one.</p>
</section>"""


def excluded_panel(exclusions: list[dict[str, str]]) -> str:
    if not exclusions:
        return ""
    items = "".join(
        f'<div class="excl"><span>{e(x["supplier_name"])}</span>'
        f'<span class="why">{e(x["reason"])}</span></div>'
        for x in exclusions
    )
    return f"""
<section>
  <h2>Linked in ERPNext but not called ({len(exclusions)})</h2>
  {items}
  <p class="note">A supplier whose number isn't valid E.164 never becomes a
  record at all, so nothing downstream can dial it. The number is shown masked
  even here.</p>
</section>"""


def script_panel(shortage: Shortage, supplier: SupplierRecord) -> str:
    text = sourcing_task_text(shortage, supplier)
    disclosure, _, body = text.partition("\n\n")
    return f"""
<section>
  <h2>What we say — {e(supplier.supplier_name)}</h2>
  <div class="script disc">{e(disclosure)}</div>
  <p class="note">The disclosure is built into the script. There is no argument,
  setting, or flag that produces a version without it.</p>
  <div class="script" style="margin-top:12px">{e(body)}</div>
  <p class="note">Two things are deliberately absent: our contract price of
  {e(supplier.contract_unit_price)} {e(supplier.currency.value)} (we want their
  number, not an anchor to ours) and the supplier's phone number, which travels
  separately as part of placing the call.</p>
</section>"""


def answer_sheet_panel() -> str:
    props = RESULT_SCHEMA["properties"]
    rows = []
    for name, spec in props.items():
        allowed = spec.get("enum")
        detail = (
            " · ".join(e(v) for v in allowed) if allowed else e(spec.get("type", ""))
        )
        key = ' key' if name == "stock_status" else ""
        rows.append(f'<div class="field{key}"><b class="mono">{e(name)}</b>'
                    f'<span>{detail}</span></div>')
    return f"""
<section>
  <h2>What must come back — the answer sheet</h2>
  {"".join(rows)}
  <p class="note"><b>stock_status</b> is the whole point: it separates "in stock
  and free" from "in stock but already promised to someone else". A yes/no
  availability question would never catch that. Every judgement field allows
  <span class="mono">unknown</span>, so the agent is never forced to guess.</p>
</section>"""


def guards_panel(supplier: SupplierRecord) -> str:
    guards = [
        ("CALLE_API_KEY", bool(os.environ.get("CALLE_API_KEY")), "a CALL-E key"),
        (
            "TEST_CALL_DESTINATION_NUMBER",
            bool(os.environ.get("TEST_CALL_DESTINATION_NUMBER")),
            "a number you control — the rehearsal override",
        ),
        (
            "CALLE_LIVE_TEST_CONFIRM",
            os.environ.get("CALLE_LIVE_TEST_CONFIRM") == "yes-call-my-phone",
            "set to exactly yes-call-my-phone",
        ),
    ]
    rows = "".join(
        f'<div class="guard"><span class="mark {"yes" if ok else "no"}">'
        f'{"✓" if ok else "✗"}</span><span><b class="mono">{e(name)}</b> — {e(what)}</span></div>'
        for name, ok, what in guards
    )
    return f"""
<section>
  <h2>Placing the call</h2>
  {rows}
  <button disabled>Call {e(supplier.supplier_name)} — not available from this screen</button>
  <div class="stop">This screen cannot dial. Live calling is a deliberate act at
  the terminal (<span class="mono">./run.sh call</span>) with all three guards
  set, never a button click — and it dials <em>your</em> number, not the
  supplier's.</div>
</section>"""


def page(title: str, body: str) -> HTMLResponse:
