@app.get("/", response_class=HTMLResponse)
def dashboard(
    incident: str = DEMO_INCIDENT_ID,
    part: str = DEMO_PART_NUMBER,
    supplier: str | None = None,
) -> HTMLResponse:
    erp = record()
    try:
        shortage = erp.incident(incident)
    except IncidentNotFound:
        return page(
            "SupplyGuard",
            f'<main><section><h2>No such incident</h2>'
            f'<p class="mono">{e(incident)} does not exist in the system of '
            f'record. A missing incident is an error, never an empty result.</p>'
            f'</section></main>',
        )

    suppliers = erp.approved_suppliers_for(part or shortage.part_number)
    exclusions = erp.last_exclusions
    chosen = next(
        (s for s in suppliers if s.supplier_id == supplier),
        suppliers[0] if suppliers else None,
    )

    source = "live ERPNext" if LIVE_ERP else "offline demo data"
    header = f"""
<header>
  <h1>SupplyGuard</h1>
  <span class="badge rehearsal">rehearsal — no call placed</span>
  <span class="sub">system of record: {e(source)}</span>
  <span class="sub" style="margin-left:auto">Meridian Motors</span>
</header>"""

    if chosen is None:
        right = ('<section><h2>Nobody to call</h2><p>No approved supplier for '
                 f'<span class="mono">{e(part)}</span>.</p></section>')
    else:
        right = (
            script_panel(shortage, chosen)
            + answer_sheet_panel()
            + guards_panel(chosen)
        )

    left = incident_panel(shortage) + queue_panel(suppliers, chosen) + excluded_panel(exclusions)
    return page("SupplyGuard", f"{header}<main><div>{left}</div><div>{right}</div></main>")
