"""Turning a finished call into a claim — Building Block 5.

A claim is what a supplier *said*. It is never a fact, and it is never merged
with what our own records say — keeping those two apart at the data level is
the entire point of the product.

The rule that matters most here: this module is never allowed to crash the run.
A garbled, incomplete, or entirely missing call result still produces a valid
claim — every field defaulted to "unknown" (or zero, or "not stated") and
confidence 0. That is deliberate, not a shortcut: a later phase distrusts any
claim below a confidence threshold, so a broken call flows naturally into "we
couldn't verify this one" instead of halting the shortage response partway.
"""

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import Any

from pydantic import BaseModel, ConfigDict, Field

from supplyguard.vocab import Currency, StockStatus, YesNoUnknown

NOT_STATED = "not stated"


class Claim(BaseModel):
    """The structured outcome of one phone call, before anyone judges it."""

    model_config = ConfigDict(frozen=True)

    supplier_id: str
    supplier_name: str = ""
    incident_id: str = ""
    call_round: int = 1
    call_id: str = ""
    placed_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    mode: str = "rehearsal"

    units_offered: int = 0
    earliest_availability: str = NOT_STATED
    price_quoted: YesNoUnknown = YesNoUnknown.UNKNOWN
    unit_price_quoted: Decimal = Decimal("0")
    currency: Currency = Currency.UNKNOWN
    certification_current: YesNoUnknown = YesNoUnknown.UNKNOWN
    part_number_confirmed: YesNoUnknown = YesNoUnknown.UNKNOWN

    #: The single most important field. "We have some" and "we have some, and
    #: they're yours" are different answers; a yes/no availability question
    #: would never separate them.
    stock_status: StockStatus = StockStatus.UNKNOWN

    #: 0 means "this call produced nothing we can rely on".
    confidence: float = 0.0
    evidence: tuple[str, ...] = ()

    @property
    def is_usable(self) -> bool:
        return self.confidence > 0.0

    @property
    def units_genuinely_free(self) -> int:
        """Units the supplier says are both available *and* unspoken-for.

        Anything other than "on hand and unallocated" contributes zero, because
        nothing else is a promise this factory can actually draw on.
        """
        return (
            self.units_offered
            if self.stock_status is StockStatus.ON_HAND_UNALLOCATED
            else 0
        )


def _int(value: Any) -> int:
    try:
        return max(0, int(Decimal(str(value))))
    except (TypeError, ValueError, ArithmeticError, InvalidOperation):
        return 0


def _decimal(value: Any) -> Decimal:
    try:
        parsed = Decimal(str(value))
    except (TypeError, ValueError, ArithmeticError, InvalidOperation):
        return Decimal("0")
    return parsed if parsed >= 0 else Decimal("0")


def _text(value: Any) -> str:
    if value is None:
        return NOT_STATED
    text = str(value).strip()
    return text or NOT_STATED


def _yes_no_unknown(value: Any) -> YesNoUnknown:
    try:
        return YesNoUnknown(str(value).strip().lower())
    except ValueError:
        return YesNoUnknown.UNKNOWN


def _stock_status(value: Any) -> StockStatus:
    try:
        return StockStatus(str(value).strip().lower())
    except ValueError:
        return StockStatus.UNKNOWN


def _evidence(value: Any) -> tuple[str, ...]:
    if isinstance(value, str):
        return (value,) if value.strip() else ()
    if isinstance(value, (list, tuple)):
        return tuple(str(v).strip() for v in value if str(v).strip())
    return ()


def _confidence(result: dict[str, Any], fields_understood: int) -> float:
    """Trust the caller's own confidence when it gives one; otherwise infer it
    from how much of the answer sheet actually came back understood."""
    stated = result.get("confidence")
    if stated is not None:
        try:
            return min(1.0, max(0.0, float(stated)))
        except (TypeError, ValueError):
            pass
    return round(fields_understood / 8, 2)


def claim_from_call_result(
    result: Any,
    *,
    supplier_id: str,
    supplier_name: str = "",
    incident_id: str = "",
    call_round: int = 1,
    call_id: str = "",
    mode: str = "rehearsal",
) -> Claim:
    """Always returns a Claim. Never raises, whatever `result` turns out to be.

    A result that is None, a string, a list, missing every field, or full of
    values that match nothing in the vocabulary all converge on the same safe
    outcome: an all-unknown claim with confidence 0.
    """
    base = {
        "supplier_id": supplier_id,
        "supplier_name": supplier_name,
        "incident_id": incident_id,
        "call_round": call_round,
        "call_id": call_id,
        "mode": mode,
    }

    if not isinstance(result, dict):
        return Claim(**base, confidence=0.0)

    # CALL-E may nest the answer sheet; accept either shape.
    for key in ("structured_result", "result", "data"):
        nested = result.get(key)
        if isinstance(nested, dict):
            result = {**result, **nested}
            break

    price_quoted = _yes_no_unknown(result.get("price_quoted"))
    certification = _yes_no_unknown(result.get("certification_current"))
    part_confirmed = _yes_no_unknown(result.get("part_number_confirmed"))
    stock_status = _stock_status(result.get("stock_status"))
    currency = Currency.parse(result.get("currency"))
    earliest = _text(result.get("earliest_availability"))
    units = _int(result.get("available_quantity"))
    unit_price = _decimal(result.get("unit_price_quoted"))

    understood = sum(
        [
            units > 0,
            earliest != NOT_STATED,
            price_quoted is not YesNoUnknown.UNKNOWN,
            unit_price > 0,
            currency is not Currency.UNKNOWN,
            certification is not YesNoUnknown.UNKNOWN,
            part_confirmed is not YesNoUnknown.UNKNOWN,
            stock_status is not StockStatus.UNKNOWN,
        ]
    )

    try:
        return Claim(
            **base,
            units_offered=units,
            earliest_availability=earliest,
            price_quoted=price_quoted,
            unit_price_quoted=unit_price,
            currency=currency,
            certification_current=certification,
            part_number_confirmed=part_confirmed,
            stock_status=stock_status,
            confidence=_confidence(result, understood),
            evidence=_evidence(result.get("evidence")),
        )
    except Exception:  # a validator we didn't anticipate must not stop the run
        return Claim(**base, confidence=0.0)
